   117	    objective: m ? { goal: m.goal, where: ctx.mem.subObjective ? `First: ${ctx.mem.subObjective}; then ${m.maps.join(' / ')}` : missingNeed(m, gs) ? `${missingNeed(m, gs)!.maps.join(' / ')} first (you don't have ${missingNeed(m, gs)!.what} yet), then ${m.maps.join(' / ')}` : m.maps.join(' / '), typicalOpponentLevel: m.level } : 'Game complete',
   118	    partyHealth: maxHp ? `${Math.round((100 * hp) / maxHp)}% total HP, ${party.filter((p) => p.hp === 0).length} fainted` : 'no Pokémon',
   119	    strongestLevel: Math.max(0, ...party.map((p) => p.level)),
   120	    teamSize: `${party.length}/6`,
   121	    // type-chart facts: how each team member matches up against the objective's opponents
   122	    teamVsObjective: m?.types ? party.map((p) => {
