   109	/** Compact, Jev-facing summary of the player situation (shared across decision types). */
   110	export function situation(ctx: Ctx) {
   111	  const { gs } = ctx;
   112	  const { m } = currentMilestone(gs);
   113	  const party = gs.party();
   114	  const hp = party.reduce((a, p) => a + p.hp, 0), maxHp = party.reduce((a, p) => a + p.maxHp, 0);
   115	  return {
   116	    fieldMoveNeeded: ctx.mem.fieldMoveNeeded ? fieldMoveFact(ctx, ctx.mem.fieldMoveNeeded) : undefined,
   117	    objective: m ? { goal: m.goal, where: ctx.mem.subObjective ? `First: ${ctx.mem.subObjective}; then ${m.maps.join(' / ')}` : missingNeed(m, gs) ? `${missingNeed(m, gs)!.maps.join(' / ')} first (you don't have ${missingNeed(m, gs)!.what} yet), then ${m.maps.join(' / ')}` : m.maps.join(' / '), typicalOpponentLevel: m.level } : 'Game complete',
   118	    partyHealth: maxHp ? `${Math.round((100 * hp) / maxHp)}% total HP, ${party.filter((p) => p.hp === 0).length} fainted` : 'no Pokémon',
   119	    strongestLevel: Math.max(0, ...party.map((p) => p.level)),
   120	    teamSize: `${party.length}/6`,
   121	    // type-chart facts: how each team member matches up against the objective's opponents
   122	    teamVsObjective: m?.types ? party.map((p) => {
   123	      const eff = (ts: string[]) => Math.max(0, ...p.moves.filter((mv) => mv.power > 0).map((mv) => ctx.rom.effectiveness(mv.type, ts)));
   124	      const best = m.dualType ? eff(m.types!) : Math.max(...m.types!.map((t) => eff([t])));
   125	      const threat = Math.max(...m.types!.map((t) => ctx.rom.effectiveness(t, p.types)));
   126	      const word = (x: number) => (x === 0 ? 'no effect' : x >= 2 ? `super effective x${x}` : x < 1 ? `not very effective x${x}` : 'normal effectiveness');
   127	      const attacks = p.moves.some((mv) => mv.power > 0) ? `best move vs ${m.types!.join('/')} is ${word(best)}` : 'has no damaging moves';
   128	      return `${p.species} Lv${p.level}: ${attacks}; ${m.types!.join('/')} moves are ${word(threat)} against it`;
   129	    }) : undefined,
   130	    // where the player reappears if every Pokémon faints (the last Pokémon Center used); losing also halves money
   131	    returnPointIfAllFaint: `Pokémon Center in ${mapName(gs.u8('wLastBlackoutMap'))}`,
   132	    lossesSoFar: Object.keys(ctx.mem.losses ?? {}).length ? Object.entries(ctx.mem.losses!).map(([m, l]) => `All Pokémon fainted at ${m} ${l.count} time(s); team at the last one: ${l.team}`) : undefined,
   133	    pokeBalls: gs.bag().filter((i) => /BALL$/.test(i.name)).reduce((a, i) => a + i.qty, 0),
   134	    location: gs.mapName,
   135	    badges: gs.badgeCount,
   136	    money: gs.money,
   137	    party: gs.party().map((p) => ({
   138	      name: p.nickname, species: p.species, level: p.level, hp: `${p.hp}/${p.maxHp}`, status: p.status, types: p.types.join('/'),
   139	      moves: p.moves.map((mv) => `${mv.name} (${mv.type}, pow ${mv.power}, ${mv.pp}/${mv.maxPp}pp)`),
   140	    })),
   141	    bag: gs.bag().map((i) => `${i.name} x${i.qty}`),
