    49	static uint64_t mScriptMakeBitmask(struct mScriptList* list) {
    50		size_t i;
    51		uint64_t mask = 0;
    52		for (i = 0; i < mScriptListSize(list); ++i) {
    53			struct mScriptValue bit;
    54			struct mScriptValue* value = mScriptListGetPointer(list, i);
    55			if (value->type->base == mSCRIPT_TYPE_WRAPPER) {
    56				value = mScriptValueUnwrap(value);
    57			}
    58			if (!mScriptCast(mSCRIPT_TYPE_MS_U64, value, &bit)) {
    59				continue;
    60			}
    61			mask |= 1ULL << bit.value.u64;
    62		}
    63		return mask;
    64	}
    65	
    66	static struct mScriptValue* mScriptExpandBitmask(uint64_t mask) {
    67		struct mScriptValue* list = mScriptValueAlloc(mSCRIPT_TYPE_MS_LIST);
    68		size_t i;
    69		for (i = 0; mask; ++i, mask >>= 1) {
    70			if (!(mask & 1)) {
    71				continue;
    72			}
    73			*mScriptListAppend(list->value.list) = mSCRIPT_MAKE_U32(i);
    74		}
    75		return list;
    76	}
